// This file is generated by AI.

// 文档落盘队列: 同一份文档的写入**按发起顺序**执行, 且只在内容仍然有效时回执 (清脏)。
//
// 自动保存是异步的, 而用户不会等它 —— 落盘期间继续敲字是常态。踩过的两处竞态:
//
// 1. 写入前取一份内容, 写入完成后拿**那一份**回执。若期间用户又敲了字, 编辑器里的
//    文档就被这份旧内容回退 (编辑器照文档状态回灌), 刚敲的字凭空消失, 撤销栈里还多出
//    一条整档替换, 此后撤回/重做全部错位;
// 2. 两次保存并发时写入顺序不定, 磁盘上可能留下更旧的一份。
//
// 这里: 写入串行排队, 且回执前重新取一次当前内容 —— 内容变了就不回执, 脏标记留着,
// 下一次自动保存会再写一遍。
//
// 纯逻辑, 不认识编辑器与 Tauri: 读写都从外部注入。

export interface DocumentSaver {
  /** 排队写一次盘; 返回的 Promise 在该次写入与回执完成后 resolve */
  save(): Promise<void>;
  /** 是否还有未完成的写入 (含排队等待中的) */
  readonly pending: boolean;
}

export interface DocumentSaverOptions {
  /** 读取当前内容 (写入前与回执前各读一次) */
  read: () => string;
  write: (text: string) => Promise<void>;
  /** 写入完成且内容仍然有效时的回执 (通常是"记录内容 + 清脏") */
  commit: (text: string) => void;
  onError?: (error: unknown) => void;
}

export function createDocumentSaver(options: DocumentSaverOptions): DocumentSaver {
  let chain: Promise<void> = Promise.resolve();
  let inflight = 0;

  const save = (): Promise<void> => {
    inflight += 1;
    // 串行: 前一次写入没落地就不再开始下一次, 免得磁盘上的内容由完成顺序决定
    chain = chain.then(async () => {
      try {
        const text = options.read();
        await options.write(text);
        // 落盘期间用户可能又改了: 这份内容已经过期, 回执会把它倒退回去
        if (options.read() !== text) return;
        options.commit(text);
      } catch (error) {
        options.onError?.(error);
      } finally {
        inflight -= 1;
      }
    });
    return chain;
  };

  return {
    save,
    get pending() {
      return inflight > 0;
    },
  };
}
